[CmdletBinding()] param([string]$InstallRoot="$env:ProgramData\PDCMonitor\Staging",[string]$ToRelease)
$ErrorActionPreference='Stop';$service='PDC-PMB-Email-Monitor-Staging';Stop-ScheduledTask -TaskName $service -ErrorAction SilentlyContinue;Disable-ScheduledTask -TaskName $service -ErrorAction SilentlyContinue|Out-Null
if($ToRelease){$target=Join-Path $InstallRoot ("releases\"+$ToRelease);if(-not(Test-Path (Join-Path $target 'release-manifest.json'))){throw 'Rollback release not found.'};$releaseChecksum=Join-Path $target 'MANIFEST_SHA256';if(-not(Test-Path $releaseChecksum)){throw 'Rollback release checksum not found.'};$expected=(Get-Content $releaseChecksum -Raw).Trim();& (Join-Path $target 'scripts\verify.ps1') -BundleRoot $target -ExpectedManifestSha256 $expected;if($LASTEXITCODE -ne 0){throw 'Rollback release verification failed.'};Set-Content (Join-Path $InstallRoot 'CURRENT') $ToRelease -Encoding ascii;Set-Content (Join-Path $InstallRoot 'MANIFEST_SHA256') $expected -Encoding ascii}
[pscustomobject]@{ok=$true;task=$service;enabled=$false;stopped=$true;selected_release=$ToRelease;intake_started=$false}|ConvertTo-Json -Compress
